import React, { useEffect, useState } from "react";
import Papa from "papaparse";
import { BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid, Legend, ResponsiveContainer, ScatterChart, Scatter } from "recharts";

function App() {
  const [data, setData] = useState([]);
  const [region, setRegion] = useState("All");

  useEffect(() => {
    fetch("/merged-gdb-cpi.csv")
      .then(res => res.text())
      .then(text => {
        Papa.parse(text, {
          header: true,
          skipEmptyLines: true,
          complete: (results) => setData(results.data),
        });
      });
  }, []);

  const regions = Array.from(new Set(data.map(d => d["Region"]))).filter(Boolean);

  const filteredData = region === "All" ? data : data.filter(d => d["Region"] === region);

  const barData = filteredData.map(row => ({
    country: row["Country"],
    Lobbying: Number(row["Lobbying"]) || 0,
    PoliticalFinance: Number(row["Political Finance Score"]) || 0,
  }));

  const scatterData = filteredData.map(row => ({
    country: row["Country"],
    integrity: ((Number(row["Lobbying"]) || 0) + (Number(row["Political Finance Score"]) || 0)) / 2,
    cpi: Number(row["CPI Score 2024"]) || 0,
  }));

  return (
    <div className="p-4 font-sans">
      <h1 className="text-3xl font-bold mb-4">GDB & CPI Transparency Dashboard</h1>
      <p className="mb-4">Explore how political integrity scores relate to perceived corruption levels globally.</p>
      <p className="mb-4">This dashboard investigates the relationship between political integrity (specifically Political Finance and Lobbying transparency) and the Corruption Perceptions Index (CPI) 2024.

It highlights how countries with stronger political finance frameworks tend to have lower perceived corruption, while also uncovering a striking data gap — the near absence of lobbying transparency data across most countries.</p>
      <div className="mb-4">
        <label className="mr-2">Filter by Region:</label>
        <select className="border p-2" onChange={(e) => setRegion(e.target.value)} value={region}>
          <option value="All">All</option>
          {regions.map((r, i) => <option key={i} value={r}>{r}</option>)}
        </select>
      </div>

      <div className="mb-8 bg-white p-4 shadow rounded">
        <h2 className="text-xl font-semibold mb-2">Political Integrity Scores</h2>
        <ResponsiveContainer width="100%" height={400}>
          <BarChart data={barData}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="country" angle={-45} textAnchor="end" interval={0} height={100} />
            <YAxis />
            <Tooltip />
            <Legend />
            <Bar dataKey="Lobbying" fill="#4c78a8" />
            <Bar dataKey="PoliticalFinance" fill="#f58518" />
          </BarChart>
        </ResponsiveContainer>
      </div>

      <div className="mb-8 bg-white p-4 shadow rounded">
        <h2 className="text-xl font-semibold mb-2">Integrity vs. CPI Correlation</h2>
        <ResponsiveContainer width="100%" height={400}>
          <ScatterChart>
            <CartesianGrid />
            <XAxis type="number" dataKey="integrity" name="Political Integrity" unit="" />
            <YAxis type="number" dataKey="cpi" name="CPI Score" unit="" />
            <Tooltip cursor={{ strokeDasharray: "3 3" }} />
            <Scatter name="Countries" data={scatterData} fill="#8884d8" />
          </ScatterChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

export default App;
